pub fn toCssWithParensIfNeeded(self: SupportsCondition, dest: *css.Printer, needs_parens: bool) css.PrintErr!void {
            if (needs_parens) {
                _ = try dest.writeStr("(");
            }
            _ = try self.toCss(dest);
            if (needs_parens) {
                _ = try dest.writeStr(")");
            }
